        "countUnit": "条",
        "bellIcon": "resources/base/media/icon_bell.png",
        "dndLabel": "通勤勿扰",
        "dndEnabled": false
      },
      "groups": [
        {
          "name": "家人群",
          "unreadText": "12条",
          "done": false
        },
        {
          "name": "项目群",
