          "done": true
        }
      ],
      "alert": {
        "hasFailure": true,
        "message": "2条发送失败",
        "icon": "resources/base/media/icon_warning.png"
      },
      "data": {
        "weather": {
          "location": {
            "districtName": "当前位置",
            "prefectureName": ""
          },
          "current": {
            "temperatureText": "--",
            "condition": "读取中",
            "airQuality": "",
            "alertLevel": ""
          },
          "daily": [],
          "updatedAt": ""
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "bell_icon",
      "src": "resources/base/media/icon_bell.png",
      "use": "notification bell icon",
      "description": "系统素材库铃铛图标，用于通知聚合卡识别未读消息主题。",
      "bindTo": "/summary/bellIcon",
      "static": true
    },
    {
      "assetRef": "warning_icon",
      "src": "resources/base/media/icon_warning.png",
      "use": "send failure warning icon",
      "description": "系统素材库警示图标，用于消息发送失败时的红色提示。",
      "bindTo": "/alert/icon",
      "static": true
    }
  ]
}

